from __future__ import annotations

import typing
from dataclasses import replace

import pytest
from hypothesis import HealthCheck, given, settings, strategies as st

from llm_router import (
    LLMRouter,
    Model,
    Provider,
    ProviderLimits,
    RouterProfile,
    get_config,
    install_config,
)
from tests.llm_router.support.fault_server import (
    ScriptedHTTPServer,
    ScriptedResponse,
)
from tests.llm_router.support.workers.retry import (
    openai_chat_path,
    openai_success_response,
)
from tests.llm_router.support.workers.worker_patches import patched_openai_sdk

pytestmark = pytest.mark.verification_kind("unit")

PATH = openai_chat_path()
HEADERS = {"Content-Type": "application/json"}
FALLBACK_TEXT = "fallback answer"
NO_LIMITS = ProviderLimits(
    rps=0.0,
    rpm=0.0,
    cooldown_seconds=0.0,
    cooldown_after_failures=0,
)


class ZeroSeconds:
    """A zero-second timeout that is falsy and still waits like a number."""

    def __bool__(self) -> bool:
        return False

    def __float__(self) -> float:
        return 0.0

    def __index__(self) -> int:
        return 0

    def __gt__(self, other: object) -> bool:
        return False

    def __le__(self, other: object) -> bool:
        return True


@pytest.fixture(autouse=True)
def credentials(monkeypatch: pytest.MonkeyPatch) -> None:
    """Provide local credentials for configured providers."""
    value = "local-test-credential"
    monkeypatch.setenv("OPENROUTER_API_KEY_1", value)
    monkeypatch.setenv("GROQ_API_KEY_1", value)


@pytest.fixture
def no_attempt_timeout() -> typing.Iterator[None]:
    """Install a config whose policy sets no attempt timeout, then restore."""
    original = get_config()
    defaults = original.defaults
    policy = replace(defaults.policy, attempt_timeout_seconds=None)
    install_config(replace(original, defaults=replace(defaults, policy=policy)))
    yield
    install_config(original)


def make_router(
    profiles: RouterProfile | list[RouterProfile],
    *,
    timeout_seconds: float | None | ZeroSeconds,
) -> LLMRouter:
    """Build a test router with disabled limits."""
    return LLMRouter(
        profiles,
        limits_by_provider={
            Provider.OPENROUTER: NO_LIMITS,
            Provider.GROQ: NO_LIMITS,
        },
        attempt_timeout_seconds=timeout_seconds,
    )


@pytest.mark.verifies("REQ_ROUTE_TIMEOUT_FALLBACK[revision==1]")
@pytest.mark.usefixtures("no_attempt_timeout")
def test_sync_no_timeout_returns_provider_response() -> None:
    routes = {
        ("POST", PATH): [
            ScriptedResponse(
                status_code=200,
                headers=HEADERS,
                body=openai_success_response(text="plain answer"),
            )
        ]
    }
    with (
        ScriptedHTTPServer(port=0, routes=routes) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = make_router(
            RouterProfile(
                model=Model.DEEPSEEK_V3,
                provider=Provider.OPENROUTER,
            ),
            timeout_seconds=None,
        )
        response = router.query("test-prompt")

    assert response.output_text == "plain answer"


@pytest.mark.verifies("REQ_ROUTE_TIMEOUT_FALLBACK[revision==1]")
def test_sync_zero_attempt_timeout_surfaces_public_timeout() -> None:
    routes = {
        ("POST", PATH): [
            ScriptedResponse(
                status_code=200,
                headers=HEADERS,
                body=openai_success_response(text="slow-only-route"),
                delay_seconds=0.5,
            )
        ]
    }
    with (
        ScriptedHTTPServer(port=0, routes=routes) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = make_router(
            RouterProfile(
                model=Model.DEEPSEEK_V3,
                provider=Provider.OPENROUTER,
            ),
            timeout_seconds=ZeroSeconds(),
        )
        with pytest.raises(TimeoutError, match=r"Attempt timed out"):
            router.query("test-prompt")


@pytest.mark.verifies("REQ_ROUTE_TIMEOUT_FALLBACK[revision==1]")
def test_sync_timeout_moves_to_fallback_without_grace_wait() -> None:
    routes = {
        ("POST", PATH): [
            ScriptedResponse(
                status_code=200,
                headers=HEADERS,
                body=openai_success_response(text="slow answer"),
                delay_seconds=0.15,
            ),
            ScriptedResponse(
                status_code=200,
                headers=HEADERS,
                body=openai_success_response(text=FALLBACK_TEXT),
            ),
        ]
    }
    with (
        ScriptedHTTPServer(port=0, routes=routes) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = make_router(
            [
                RouterProfile(
                    model=Model.DEEPSEEK_V3,
                    provider=Provider.OPENROUTER,
                ),
                RouterProfile(
                    model=Model.LLAMA_SCOUT,
                    provider=Provider.GROQ,
                ),
            ],
            timeout_seconds=0.1,
        )
        response = router.query("test-prompt")

    assert response.output_text == FALLBACK_TEXT
    first_attempt = next(iter(response.routing_trace))
    assert first_attempt.error_type == "TimeoutError"


@pytest.mark.verifies("REQ_ROUTE_TIMEOUT_FALLBACK[revision==1]")
@settings(
    max_examples=1,
    deadline=450,
    database=None,
    suppress_health_check=[HealthCheck.function_scoped_fixture],
)
@given(prompt=st.just("Reply with the fallback marker only."))
def test_sync_timeout_falls_back_without_waiting_for_slow_route(
    prompt: str,
) -> None:
    routes = {
        ("POST", PATH): [
            ScriptedResponse(
                status_code=200,
                headers=HEADERS,
                body=openai_success_response(text="slow answer"),
                delay_seconds=0.8,
            ),
            ScriptedResponse(
                status_code=200,
                headers=HEADERS,
                body=openai_success_response(text=FALLBACK_TEXT),
            ),
        ]
    }
    with (
        ScriptedHTTPServer(port=0, routes=routes) as server,
        patched_openai_sdk(
            forced_base_url=f"{server.base_url}/v1",
            disable_sdk_retries=True,
        ),
    ):
        router = make_router(
            [
                RouterProfile(
                    model=Model.DEEPSEEK_V3,
                    provider=Provider.OPENROUTER,
                ),
                RouterProfile(
                    model=Model.LLAMA_SCOUT,
                    provider=Provider.GROQ,
                ),
            ],
            timeout_seconds=0.1,
        )
        response = router.query(prompt)

    assert response.output_text == FALLBACK_TEXT
    first_attempt = next(iter(response.routing_trace))
    assert first_attempt.error_type == "TimeoutError"
